package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.village.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.core.BlockPos; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes;
public final class VillageMigrationBehaviorGameTest { @GameTest public void migrationKeepsVillageIdentity(GameTestHelper c){ var a=c.spawn(EntityTypes.VILLAGER,2,1,2); c.runAtTickTime(1,()->{TheWorldRemembers.processWorld(c.getLevel());var manager=VillageManager.get(c.getLevel().getServer());var first=manager.all().iterator().next();var id=first.villageId();a.setPos(40,1,40);c.runAtTickTime(2,()->{TheWorldRemembers.processWorld(c.getLevel());var found=manager.get(id);if(found==null){c.fail("Village identity was lost during movement");return;}if(found.center().distSqr(new BlockPos(40,1,40))>64*64){c.fail("Village center did not follow settlement");return;}c.succeed();});}); } }
